export function flexibleGameContexts(gameId: string, questId: string, installments: readonly string[]) {
  return (COMPATIBILITY_BY_GAME_QUEST.get(`${gameId}:${questId}`) ?? [])
    .filter(row => row.installmentId === null || installments.includes(row.installmentId))
    .flatMap(row => row.contexts);
}

const COMPATIBILITY_BY_GAME_QUEST = new Map<string, GameQuestCompatibility[]>();
for (const row of FLEXIBLE_GAME_COMPATIBILITY) {
  const key = `${row.gameId}:${row.questId}`;
  const entries = COMPATIBILITY_BY_GAME_QUEST.get(key) ?? [];
  entries.push(row);
  COMPATIBILITY_BY_GAME_QUEST.set(key, entries);
}
